package mz.bam.seeky.android;
import java.util.*;
public final class PageTurnPolicyCheck {
 static int checks;static void ok(boolean b,String s){if(!b)throw new AssertionError(s);checks++;System.out.println("PASS "+s);}
 public static void main(String[] args){PageSwipe p=new PageSwipe(24,56,500);p.begin(300,100,0);ok(p.move(200,105,60,1,false),"deliberate horizontal movement locks");ok(p.end(50,105,180,1,false)==1,"left swipe turns forward");p.begin(50,100,0);ok(p.end(250,110,180,1,false)==-1,"right swipe turns back");p.begin(300,100,0);ok(p.end(260,105,150,1,false)==0,"small drag does not turn");p.begin(200,300,0);ok(!p.move(205,190,70,1,false),"vertical scrolling remains vertical");ok(p.end(10,190,180,1,false)==0,"late horizontal movement cannot steal a vertical scroll");p.begin(300,100,0);ok(p.end(50,105,650,1,false)==0,"long press preserves selection gesture");p.begin(300,100,0);p.move(200,105,60,2,false);ok(p.end(50,105,180,1,false)==0,"second pointer cancels page turn");p.begin(300,100,0);ok(p.end(50,105,180,1,true)==0,"selected text keeps ownership");ok(p.end(50,105,180,1,false)==0,"completed gesture cannot fire twice");
 ok(TextPaging.target(0,1,600,4000,24)==552,"viewport turn overlaps two text lines");ok(TextPaging.target(0,-1,600,4000,24)==0,"previous at start clamps to zero");ok(TextPaging.target(3300,1,600,4000,24)==3400,"next screen clamps at chapter end");ok(TextPaging.target(0,1,600,300,24)==0,"a short chapter has no invented extra screen");ok(TextPaging.target(Integer.MAX_VALUE,1,10,Integer.MAX_VALUE,1)==Integer.MAX_VALUE-10,"paging arithmetic cannot overflow");
 ok(VoiceIdentity.explicitGender(Collections.singleton("gender=female"))==1,"explicit female metadata is accepted");ok(VoiceIdentity.explicitGender(Collections.singleton("gender:male"))==2,"explicit male metadata is accepted");ok(VoiceIdentity.explicitGender(Collections.singleton("pt-br-x-opaque"))==0,"gender is not guessed from internal voice IDs");ok(!VoiceIdentity.key("a","v").equals(VoiceIdentity.key("b","v")),"voice notes are scoped to their engine");System.out.println("PASS "+checks+" gesture, paging and voice identity policy checks");}
}
